insert into settings select * from json_populate_record(null::settings, E'{"key":"terms","value":"Warunki współpracy z Pimp My Bar\\n\\nForma współpracy\\n\\n1. Pracujesz jako podwykonawca na konkretne eventy. Studenci do 26 r.ż. — umowa zlecenie (bez ZUS). Pozostali — umowa zlecenie z ZUS albo faktura, jeśli masz działalność.\\n2. Do umowy potrzebujemy: imię, nazwisko, PESEL, adres, numer konta, a od studentów skan legitymacji. Podajesz je raz, przy pierwszym evencie.\\n\\nStawka i wypłata\\n\\n3. Stawka jest ustalana indywidualnie na każdy event i podawana w zaproszeniu, zanim potwierdzisz.\\n4. Wypłata: gotówką po evencie, [w poniedziałek po weekendzie / do 7 dni] — zależnie od eventu, zawsze napisane przy stawce.\\n5. Napiwki: nie wnikamy w napiwki.\\n6. Dojazd na zbiórkę do magazynu jest po Twojej stronie. Dalej jedziemy autami PMB albo zwracamy paliwo, jeśli jedziesz swoim (ustalane przy evencie).\\n\\nPotwierdzenia i odwołania\\n\\n7. Zaproszenie na event potwierdzasz kliknięciem „Wchodzę”. Od tego momentu liczymy na Ciebie i nie szukamy nikogo na Twoje miejsce.\\n8. Jeśli musisz odwołać: najpóźniej [72 h / 5 dni] przed eventem, telefonicznie do Tomka, nie SMS-em. Odwołanie w ostatniej chwili albo niepojawienie się bez kontaktu kończy współpracę.\\n9. Jeśli my odwołamy event z winy klienta w ostatnie [48 h], dostajesz [20% stawki / stawkę za gotowość].\\n\\nPrzed eventem\\n\\n10. Zbiórka jest w agendzie pod Twoim linkiem: miejsce, godzina, co spakować. Standardowo magazyn PMB, ul. Szarych Szeregów 25A (Pekabud Market, koniec hali, niebieska furtka).\\n11. Zbiórka to godzina, o której jesteśmy gotowi do pakowania, nie godzina wyjazdu z domu.\\n12. Dress code jest opisany przy każdym evencie. Domyślnie: czarna/biała koszula z długim rękawem, czarne spodnie, czarne pełne buty, fartuch PMB bądź własna kamizelka (do ustalenia). Bez logo innych firm, czapek, krótkich spodenek.\\n\\nNa evencie\\n\\n13. Zero alkoholu w trakcie pracy. Papierosy tylko w przerwie, poza zasięgiem wzroku gości.\\n14. Unikamy używania telefonu za barem.\\n15. Nie podajemy alkoholu osobom nietrzeźwym i nieletnim.\\n16. Gość jest gościem klienta, nie Twoim. Nie komentujemy imprezy, klienta ani innych ekip przy gościach ani potem publicznie.\\n17. Miejsce, w którym stał bar, zostawiamy w takim samym stanie, jak zastaliśmy przed rozłożeniem baru.\\n\\nSprzęt i pakowanie\\n\\n18. Sprzęt PMB (bary, kosze, narzędzia, klisze) to Twoja odpowiedzialność od załadunku do rozładunku.\\n19. Pakowanie odbywa się według listy w aplikacji — odhaczasz to, co ładujesz.\\n\\nDane i wizerunek\\n\\n20. Twoje dane przechowujemy tylko do umów i organizacji eventów, nie przekazujemy ich dalej. Możesz poprosić o ich usunięcie po zakończeniu współpracy.\\n21. Zgadzasz się na wykorzystanie zdjęć i wideo z eventów, na których jesteś, w materiałach PMB (strona, social media). Jeśli nie — powiedz przed pierwszym evencie.\\n\\nWspółpraca\\n\\n22. Nie podbieramy klientów PMB. Jeśli klient z eventu pyta Cię o bar na swoją imprezę, kierujesz go do Tomka.\\n23. Po każdym evencie super, jak zostawisz notatkę z uwagami o evencie. To pozwoli nam poprawiać różne rzeczy.","updated_at":"2026-08-30T18:50:51.36759+00:00"}');
insert into settings select * from json_populate_record(null::settings, E'{"key":"warehouse","value":"Magazyn PMB — ul. Szarych Szeregów 25A, Poznań (Podolany). Wjazd na teren Pekabud Market, jedziesz do końca hali, wejście niebieską furtką.\\nParking: przed magazynem wzdłuż — 4–5 miejsc parkingowych.\\nPo powrocie z eventu: rozładunek do magazynu, kosze na swoje miejsce, brudny sprzęt do strefy mycia. Lodówki / colemany otwarte do wyschnięcia.","updated_at":"2026-08-30T20:16:41.745568+00:00"}');
